int luca_pbmp_response(const char*req,const struct luca_pbmp_state*s,char*out,size_t n){if(!req||strlen(req)>4096)return-1;char id[128],m[128],network[256],name[201],reason[201];if(field(req,"id",id,sizeof id)||field(req,"method",m,sizeof m))return-1;const char*r=NULL;char dyn[768];if(!strcmp(m,"pbmp.info"))r="{\"protocol\":\"PBMP/1\",\"implementation\":\"luca\",\"version\":\"0.1.2\"}";else if(!strcmp(m,"capabilities.list"))r="{\"capabilities\":[\"pbmp.info\",\"capabilities.list\",\"bot.info\",\"networks.list\",\"channels.list\",\"channels.join\",\"channels.part\",\"modules.list\",\"modules.reload\",\"metrics.read\",\"logs.read\",\"config.schema\",\"config.read\"]}";else if(!strcmp(m,"config.schema"))r="{\"fields\":[{\"name\":\"server\",\"type\":\"string\",\"reload\":\"reconnect\"},{\"name\":\"port\",\"type\":\"string\",\"reload\":\"reconnect\"},{\"name\":\"nick\",\"type\":\"string\",\"reload\":\"reconnect\"},{\"name\":\"user\",\"type\":\"string\",\"reload\":\"reconnect\"},{\"name\":\"realname\",\"type\":\"string\",\"reload\":\"reconnect\"},{\"name\":\"channel\",\"type\":\"string\",\"reload\":\"reconnect\"},{\"name\":\"script\",\"type\":\"string\",\"reload\":\"restart\"},{\"name\":\"tls\",\"type\":\"boolean\",\"reload\":\"reconnect\"},{\"name\":\"sasl\",\"type\":\"boolean\",\"reload\":\"reconnect\"},{\"name\":\"reconnect_seconds\",\"type\":\"integer\",\"reload\":\"restart\"}]}";else if(!strcmp(m,"config.read")){snprintf(dyn,sizeof dyn,"{\"config\":{\"server\":\"%s\",\"port\":\"%s\",\"nick\":\"%s\",\"user\":\"%s\",\"realname\":\"%s\",\"channel\":\"%s\",\"script\":\"%s\",\"tls\":%s,\"sasl\":%s,\"reconnect_seconds\":%d}}",s->network,s->port,s->nick,s->user,s->realname,s->channel,s->script,s->tls?"true":"false",s->sasl?"true":"false",s->reconnect_seconds);r=dyn;}else if(!strcmp(m,"logs.read")){struct luca_log_entry e[LUCA_LOG_CAP];unsigned z=s->log?luca_log_snapshot(s->log,e,LUCA_LOG_CAP):0,off=0;off+=snprintf(dyn+off,sizeof dyn-off,"{\"entries\":[");for(unsigned i=0;i<z&&off<sizeof dyn;i++)off+=snprintf(dyn+off,sizeof dyn-off,"%s{\"level\":\"%s\",\"message\":\"%s\"}",i?",":"",e[i].level,e[i].message);snprintf(dyn+off,sizeof dyn-off,"]}");r=dyn;}else if(!strcmp(m,"metrics.read")){long up=atomic_load(&s->connected)&&atomic_load(&s->session_started)?(long)(time(NULL)-atomic_load(&s->session_started)):0;snprintf(dyn,sizeof dyn,"{\"metrics\":{\"irc.rx_lines\":%llu,\"irc.tx_lines\":%llu,\"irc.reconnects\":%llu,\"session.uptime_seconds\":%ld}}",(unsigned long long)atomic_load(&s->rx_lines),(unsigned long long)atomic_load(&s->tx_lines),(unsigned long long)atomic_load(&s->reconnects),up);r=dyn;}else if(!strcmp(m,"modules.reload")){if(field(req,"id",name,sizeof name)||!s->module_id||strcmp(name,s->module_id)||!s->commands)return snprintf(out,n,"{\"pbmp\":1,\"type\":\"response\",\"id\":\"%s\",\"ok\":false,\"error\":{\"code\":\"invalid_params\",\"message\":\"unknown module\"}}\n",id)>=(int)n?-1:0;if(luca_command_enqueue_reload(s->commands))return snprintf(out,n,"{\"pbmp\":1,\"type\":\"response\",\"id\":\"%s\",\"ok\":false,\"error\":{\"code\":\"unavailable\",\"message\":\"command queue full\"}}\n",id)>=(int)n?-1:0;snprintf(dyn,sizeof dyn,"{\"id\":\"%s\",\"state\":\"reloading\"}",name);r=dyn;}else if(!strcmp(m,"modules.list")){if(s->module_id&&s->module_id[0])snprintf(dyn,sizeof dyn,"{\"modules\":[{\"id\":\"%s\",\"runtime\":\"lua\",\"state\":\"%s\"}]}",s->module_id,atomic_load(&s->module_active)?"active":"error");else snprintf(dyn,sizeof dyn,"{\"modules\":[]}");r=dyn;}else if(!strcmp(m,"bot.info")){snprintf(dyn,sizeof dyn,"{\"implementation\":\"luca\",\"version\":\"0.1.2\",\"nick\":\"%s\",\"state\":\"%s\"}",s->nick,atomic_load(&s->connected)?"online":"offline");r=dyn;}else if(!strcmp(m,"networks.list")){snprintf(dyn,sizeof dyn,"{\"networks\":[{\"name\":\"%s\",\"state\":\"%s\"}]}",s->network,atomic_load(&s->connected)?"connected":"disconnected");r=dyn;}else if(!strcmp(m,"channels.join")||!strcmp(m,"channels.part")){int bad=field(req,"network",network,sizeof network)||field(req,"name",name,sizeof name)||strcmp(network,s->network)||!atomic_load(&s->connected)||!s->commands||strlen(name)<2||!strchr("#&+!",name[0])||strpbrk(name," ,\r\n");if(bad)return snprintf(out,n,"{\"pbmp\":1,\"type\":\"response\",\"id\":\"%s\",\"ok\":false,\"error\":{\"code\":\"invalid_params\",\"message\":\"invalid or unavailable channel request\"}}\n",id)>=(int)n?-1:0;char line[512];if(!strcmp(m,"channels.join"))snprintf(line,sizeof line,"JOIN %s",name);else{reason[0]=0;field(req,"reason",reason,sizeof reason);if(reason[0])snprintf(line,sizeof line,"PART %s :%s",name,reason);else snprintf(line,sizeof line,"PART %s",name);}if(luca_command_enqueue(s->commands,line))return snprintf(out,n,"{\"pbmp\":1,\"type\":\"response\",\"id\":\"%s\",\"ok\":false,\"error\":{\"code\":\"unavailable\",\"message\":\"command queue full\"}}\n",id)>=(int)n?-1:0;snprintf(dyn,sizeof dyn,"{\"network\":\"%s\",\"name\":\"%s\",\"state\":\"%s\"}",network,name,!strcmp(m,"channels.join")?"joining":"parting");r=dyn;}else if(!strcmp(m,"channels.list")){if(s->channel&&s->channel[0])snprintf(dyn,sizeof dyn,"{\"channels\":[{\"network\":\"%s\",\"name\":\"%s\",\"state\":\"%s\"}]}",s->network,s->channel,atomic_load(&s->connected)?(atomic_load(&s->channel_state)==2?"joined":"joining"):"disconnected");else snprintf(dyn,sizeof dyn,"{\"channels\":[]}");r=dyn;}if(r)return snprintf(out,n,"{\"pbmp\":1,\"type\":\"response\",\"id\":\"%s\",\"ok\":true,\"result\":%s}\n",id,r)>=(int)n?-1:0;return snprintf(out,n,"{\"pbmp\":1,\"type\":\"response\",\"id\":\"%s\",\"ok\":false,\"error\":{\"code\":\"not_supported\",\"message\":\"method not supported\"}}\n",id)>=(int)n?-1:0;}
int luca_pbmp_serve(const char*path,const struct luca_pbmp_state*s){int fd=socket(AF_UNIX,SOCK_STREAM,0);if(fd<0)return-1;struct sockaddr_un a={0};a.sun_family=AF_UNIX;if(strlen(path)>=sizeof a.sun_path){close(fd);return-1;}snprintf(a.sun_path,sizeof a.sun_path,"%s",path);unlink(path);if(bind(fd,(struct sockaddr*)&a,sizeof a)||chmod(path,0600)||listen(fd,4)){close(fd);unlink(path);return-1;}for(;;){int c=accept(fd,NULL,NULL);if(c<0)continue;char in[4097],out[4096];ssize_t z=read(c,in,sizeof in);if(z>0&&z<(ssize_t)sizeof in){in[z]=0;if(!luca_pbmp_response(in,s,out,sizeof out))write(c,out,strlen(out));}close(c);}return 0;}
